using System;
using System.Diagnostics;

// PROGRAM: Pembuktian Cache Lines & Locality of Reference
// Menguji efek traversing array: Berurutan (Sequential) vs Melompat (Stride)
const int Rows = 2048;
const int Cols = 2048;
int[,] matrix = new int[Rows, Cols];

// Inisialisasi matriks
for (int r = 0; r < Rows; r++)
    for (int c = 0; c < Cols; c++)
        matrix[r, c] = 1;

// Uji 1: Row-Major (Cache-Friendly - Sesuai tata letak baris memori berurutan)
var sw = Stopwatch.StartNew();
long sumRowMajor = 0;
for (int r = 0; r < Rows; r++)
{
    for (int c = 0; c < Cols; c++)
    {
        sumRowMajor += matrix[r, c];
    }
}
sw.Stop();
Console.WriteLine($"Row-Major (Cache Hit Maksimal): {sw.ElapsedMilliseconds} ms");

