using System;

public class CacheLineCalculator
{
    public static int CalculateCacheLines(int startByteOffset, int dataLengthBytes)
    {
        if (dataLengthBytes <= 0) return 0;
        int endByte = startByteOffset + dataLengthBytes - 1;
        int startLine = startByteOffset / 64;
        int endLine = endByte / 64;
        return (endLine - startLine) + 1;
    }

    public static void Main()
    {
        Console.WriteLine($"Lines: {CalculateCacheLines(0, 64)}");
        Console.WriteLine($"Lines: {CalculateCacheLines(60, 10)}");
    }
}
